let down;
// Picking owns one primary contact only. A multi-contact gesture stays invalid
// until every contact ends; lifting the stationary pinch finger is not a tap.
const pickPointers=new Set();
const cancelPick=()=>{down=null;pickPointers.clear();};
renderer.domElement.addEventListener('pointerdown',event=>{
  pickPointers.add(event.pointerId);
  if(pickPointers.size>1||event.isPrimary===false||event.button!==0)down=null;
},true);
renderer.domElement.addEventListener('pointerdown',event=>{
  if(pickPointers.size===1&&event.isPrimary!==false&&event.button===0)down={id:event.pointerId,x:event.clientX,y:event.clientY};
});
renderer.domElement.addEventListener('pointerup',event=>{pickPointers.delete(event.pointerId);},true);
renderer.domElement.addEventListener('pointercancel',event=>{pickPointers.delete(event.pointerId);down=null;},true);
renderer.domElement.addEventListener('lostpointercapture',event=>{pickPointers.delete(event.pointerId);down=null;});
window.addEventListener('blur',cancelPick);
document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelPick();});
renderer.domElement.addEventListener('pointerup', event => {
  const start = down; down = null;
  if (loading || failed || !start || event.pointerId!==start.id || Math.hypot(event.clientX-start.x,event.clientY-start.y) > 5) return;
